#include <bits/stdc++.h>
using namespace std;

int n, m, r, c, d, occ[100];
pair<int, int> p[100];

namespace MinCostFlow {
    const int N = 10000, M = 20000000;
    int head[N], edge_idx, dist[N], prev_node[N], prev_edge[N], S, T, total_cost;
    struct Edge {
        int to, next, capacity, cost;
    } edges[M];

    void add_edge(int u, int v, int cap, int cst) {
        edges[edge_idx].to = v;
        edges[edge_idx].next = head[u];
        edges[edge_idx].capacity = cap;
        edges[edge_idx].cost = cst;
        head[u] = edge_idx++;
        edges[edge_idx].to = u;
        edges[edge_idx].next = head[v];
        edges[edge_idx].capacity = 0;
        edges[edge_idx].cost = -cst;
        head[v] = edge_idx++;
    }

    bool spfa() {
        std::fill(dist, dist + N, 0x3f3f3f3f);
        dist[S] = 0;
        std::queue<int> q;
        q.push(S);
        bool in_q[N] = {false};
        in_q[S] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            in_q[u] = false;
            for (int i = head[u]; i != -1; i = edges[i].next) {
                if (edges[i].capacity > 0 && dist[edges[i].to] > dist[u] + edges[i].cost) {
                    dist[edges[i].to] = dist[u] + edges[i].cost;
                    prev_node[edges[i].to] = u;
                    prev_edge[edges[i].to] = i;
                    if (!in_q[edges[i].to]) {
                        in_q[edges[i].to] = true;
                        q.push(edges[i].to);
                    }
                }
            }
        }
        if (dist[T] == 0x3f3f3f3f) return false;
        int flow = INT_MAX;
        for (int v = T; v != S; v = prev_node[v]) {
            flow = min(flow, edges[prev_edge[v]].capacity);
        }
        total_cost += dist[T] * flow;
        for (int v = T; v != S; v = prev_node[v]) {
            edges[prev_edge[v]].capacity -= flow;
            edges[prev_edge[v] ^ 1].capacity += flow;
        }
        return true;
    }
}

using namespace MinCostFlow;

int main() {
    scanf("%d%d%d%d%d", &n, &m, &r, &c, &d);
    memset(head, -1, sizeof(head));
    S = (r + n + 1) * n + 1;
    T = (r + n + 1) * n + 2;
    for (int i = 1, x; i <= r; i++) {
        scanf("%d", &x);
        occ[x]++;
    }
    for (int i = 1; i <= m; i++) {
        scanf("%d%d", &p[i].first, &p[i].second);
    }
    for (int i = 0; i < r + n; i++) {
        for (int j = 1; j <= m; j++) {
            for (int k = 1; k <= r; k++) {
                add_edge(i * n + p[j].first, (i + 1) * n + p[j].second, 1, (2 * k - 1) * d);
                add_edge(i * n + p[j].second, (i + 1) * n + p[j].first, 1, (2 * k - 1) * d);
            }
        }
    }
    for (int i = 1; i <= r + n; i++) {
        add_edge(i * n + 1, T, INT_MAX, i * c);
        for (int j = 2; j <= n; j++) {
            add_edge((i - 1) * n + j, i * n + j, INT_MAX, 0);
        }
    }
    for (int i = 1; i <= n; i++) {
        add_edge(S, i, occ[i], 0);
    }
    while (spfa());
    printf("%d\n", total_cost);
    return 0;
}
